import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel b8bd735:
# &packet.UpdateAbilities{AbilityData: protocol.AbilityData{
# EntityUniqueID: 7, PlayerPermissions: 2, CommandPermissions: 4,
# Layers: []protocol.AbilityLayer{
# {Type: protocol.AbilityLayerTypeBase, Abilities: protocol.AbilityFlying | protocol.AbilityMayFly,
# Values: protocol.AbilityFlying, FlySpeed: 0.05, VerticalFlySpeed: 1, WalkSpeed: 0.1},
# {Type: protocol.AbilityLayerTypeCommands, Abilities: protocol.AbilityOperatorCommands,
# Values: protocol.AbilityOperatorCommands}}}}
TWO_LAYERS = bytes.fromhex(
    "070000000000000002040201000006000000020000cdcc4c3d0000803fcdcccc3d03004000000040000000000000000000000000000000"
)

# generated by gophertunnel b8bd735:
# &packet.UpdateAbilities{AbilityData: protocol.AbilityData{
# EntityUniqueID: -1, PlayerPermissions: 0, CommandPermissions: 0}}
NO_LAYERS = bytes.fromhex("ffffffffffffffff000000")

LAYER = v2168.SerializedAbilitiesData.SerializedLayer
LAYER_KIND = v2168.SerializedAbilitiesData.SerializedAbilitiesLayer

GOLDENS = [
    pytest.param(
        v2168.UpdateAbilitiesPacket(
            data=v2168.SerializedAbilitiesData(
                target_player=7,
                player_permissions=v2168.PlayerPermissionLevel.OPERATOR,
                command_permissions=v2168.CommandPermissionLevel.OWNER,
                layers=[
                    LAYER(
                        serialized_layer=LAYER_KIND.BASE,
                        abilities_set=0x600,
                        ability_values=0x200,
                        fly_speed=0.05,
                        vertical_fly_speed=1.0,
                        walk_speed=0.1,
                    ),
                    LAYER(
                        serialized_layer=LAYER_KIND.COMMANDS,
                        abilities_set=0x40,
                        ability_values=0x40,
                        fly_speed=0.0,
                        vertical_fly_speed=0.0,
                        walk_speed=0.0,
                    ),
                ],
            )
        ),
        TWO_LAYERS,
        id="two-layers",
    ),
    pytest.param(
        v2168.UpdateAbilitiesPacket(
            data=v2168.SerializedAbilitiesData(
                target_player=-1,
                player_permissions=v2168.PlayerPermissionLevel.VISITOR,
                command_permissions=v2168.CommandPermissionLevel.ANY,
                layers=[],
            )
        ),
        NO_LAYERS,
        id="no-layers-as-a-lone-zero-count",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_update_abilities_is_packet_187(version):
    assert version.PACKETS[187] is version.UpdateAbilitiesPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_abilities_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_abilities_decodes_from_its_golden(packet, golden):
    assert v2168.UpdateAbilitiesPacket.from_bytes(golden) == packet


@pytest.fixture
def layers_128():
    return v2168.UpdateAbilitiesPacket(
        data=v2168.SerializedAbilitiesData(
            target_player=0,
            player_permissions=v2168.PlayerPermissionLevel.VISITOR,
            command_permissions=v2168.CommandPermissionLevel.ANY,
            layers=[
                LAYER(
                    serialized_layer=LAYER_KIND.BASE,
                    abilities_set=0,
                    ability_values=0,
                    fly_speed=0.0,
                    vertical_fly_speed=0.0,
                    walk_speed=0.0,
                )
            ]
            * 128,
        )
    )


def test_the_ability_layer_count_is_a_two_byte_varint_at_128(layers_128):
    wire = bytes(layers_128)
    assert len(wire) == 2828
    assert wire[10:12] == b"\x80\x01"


def test_128_ability_layers_round_trip(layers_128):
    assert v2168.UpdateAbilitiesPacket.from_bytes(bytes(layers_128)) == layers_128
